import heapq

# Tasks: (ID, duration)
tasks = {
    'T1': 2,
    'T2': 3,
    'T3': 1,
    'T4': 2
}

# Precedences: T1 -> T3; T2 -> T3; T2 -> T4
precedences = {
    'T3': ['T1', 'T2'],
    'T4': ['T2']
}

# Track dependencies remaining
in_degree = {t: 0 for t in tasks}
adj = {t: [] for t in tasks}

for target, deps in precedences.items():
    for d in deps:
        adj[d].append(target)
        in_degree[target] += 1

# Simulation with 2 workers
# Priority queue stores (finish_time, task_id)
workers = [0, 0] # Available times for worker 1 and worker 2
ready_tasks = [t for t in tasks if in_degree[t] == 0]
heapq.heapify(ready_tasks)

# Track completion times to unlock next tasks
completion_times = {}
current_time = 0

active_tasks = [] # (finish_time, task_id)
heapq.heapify(active_tasks)

while ready_tasks or active_tasks:
    # Assign available tasks to idle workers
    for i in range(len(workers)):
        if workers[i] <= current_time and ready_tasks:
            task_id = heapq.heappop(ready_tasks)
            finish_time = current_time + tasks[task_id]
            workers[i] = finish_time
            heapq.heappush(active_tasks, (finish_time, task_id))

    # Advance time to the next finished task
    if active_tasks:
        current_time, finished_task = heapq.heappop(active_tasks)
        completion_times[finished_task] = current_time

        # Check if new tasks are unlocked
        for neighbor in adj[finished_task]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(ready_tasks, neighbor)
    else:
        # This handles cases where workers might be idle but no tasks are ready yet
        if ready_tasks:
             current_time += 1 # Should not happen in this logic but for safety
        else:
            break

print(f"Minimum completion time: {max(completion_times.values())}")

